#' Estimate Phenological Peak Timing (Mode)
#'
#' Identifies the calendar Day of Year of maximum probability density across
#' simulated posterior curves. Peak coordinates are unwrapped relative to the
#' Day of Biological Year (`DOBY`) inactivity origin (`D_min`) so that winter
#' peaks straddling December 31 and January 1 are summarized without circular
#' boundary distortion before transforming back to calendar `DOY`.
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior probability density curves generated by [simulate_posterior_density()].
#' @param doby_origin Specification of the biological-year origin (`D_min`): `"auto"` (default; uses the dynamic path-tracked steepest-descent `doby_origin` attached by [simulate_posterior_density()]), `"scenario"` (computes the unconstrained global minimum directly from `sim_mat` without reference to the model baseline), an integer or numeric calendar `DOY` in `(0, 366)` for a custom cut-point, or a reference simulation matrix.
#' @return A list containing the posterior `Mean`, `Median`, `Lower_CI` (2.5%), `Upper_CI` (97.5%) on the calendar `DOY` scale, `Posterior_Draws`, and the biological minimum day `D_min`.
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' nd <- create_newdata(mod, doy = "DOY")
#' sim <- simulate_posterior_density(mod, nd, n_sims = 100, warnings = FALSE)
#' estimate_peak(sim)$Mean
#' @export
estimate_peak <- function(sim_mat, doby_origin = "auto") {
  grid <- get_doy_grid(sim_mat)
  origin <- resolve_doby_origin(doby_origin, sim_mat, two_curve = FALSE)

  shifted_mat <- sim_mat[origin$shift_order, , drop = FALSE]
  rot_peaks <- apply(shifted_mat, 2, which.max)
  t_max <- grid$doy[origin$shift_order[rot_peaks]]
  p_unwrapped <- ifelse(t_max < origin$D_min - 1e-12, t_max + 365, t_max)

  mean_unw <- mean(p_unwrapped)
  med_unw <- stats::median(p_unwrapped)
  low_unw <- stats::quantile(p_unwrapped, 0.025)
  high_unw <- stats::quantile(p_unwrapped, 0.975)

  return(list(
    Mean = wrap_unwrapped_doy(mean_unw),
    Median = wrap_unwrapped_doy(med_unw),
    Lower_CI = wrap_unwrapped_doy(low_unw),
    Upper_CI = wrap_unwrapped_doy(high_unw),
    Posterior_Draws = wrap_unwrapped_doy(p_unwrapped),
    D_min = origin$D_min
  ))
}
